/// The type of a GPU object behind a guest handle.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Kind {
    Adapter,
    BindGroup,
    BindGroupLayout,
    Buffer,
    CommandBuffer,
    CommandEncoder,
    ComputePassEncoder,
    ComputePipeline,
    Device,
    ExternalTexture,
    Instance,
    PipelineLayout,
    QuerySet,
    Queue,
    RenderBundle,
    RenderBundleEncoder,
    RenderPassEncoder,
    RenderPipeline,
    Sampler,
    ShaderModule,
    Surface,
    Texture,
    TextureView,
}

impl Kind {
    /// `wgpu*AddRef` for an object of this type.
    pub unsafe fn add_ref(self, raw: *mut c_void) {
        // SAFETY: the caller passes a live object of this type.
        unsafe {
            match self {
                Kind::Adapter => wgpuAdapterAddRef(raw as WGPUAdapter),
                Kind::BindGroup => wgpuBindGroupAddRef(raw as WGPUBindGroup),
                Kind::BindGroupLayout => wgpuBindGroupLayoutAddRef(raw as WGPUBindGroupLayout),
                Kind::Buffer => wgpuBufferAddRef(raw as WGPUBuffer),
                Kind::CommandBuffer => wgpuCommandBufferAddRef(raw as WGPUCommandBuffer),
                Kind::CommandEncoder => wgpuCommandEncoderAddRef(raw as WGPUCommandEncoder),
                Kind::ComputePassEncoder => wgpuComputePassEncoderAddRef(raw as WGPUComputePassEncoder),
                Kind::ComputePipeline => wgpuComputePipelineAddRef(raw as WGPUComputePipeline),
                Kind::Device => wgpuDeviceAddRef(raw as WGPUDevice),
                Kind::ExternalTexture => wgpuExternalTextureAddRef(raw as WGPUExternalTexture),
                Kind::Instance => wgpuInstanceAddRef(raw as WGPUInstance),
                Kind::PipelineLayout => wgpuPipelineLayoutAddRef(raw as WGPUPipelineLayout),
                Kind::QuerySet => wgpuQuerySetAddRef(raw as WGPUQuerySet),
                Kind::Queue => wgpuQueueAddRef(raw as WGPUQueue),
                Kind::RenderBundle => wgpuRenderBundleAddRef(raw as WGPURenderBundle),
                Kind::RenderBundleEncoder => wgpuRenderBundleEncoderAddRef(raw as WGPURenderBundleEncoder),
                Kind::RenderPassEncoder => wgpuRenderPassEncoderAddRef(raw as WGPURenderPassEncoder),
                Kind::RenderPipeline => wgpuRenderPipelineAddRef(raw as WGPURenderPipeline),
                Kind::Sampler => wgpuSamplerAddRef(raw as WGPUSampler),
                Kind::ShaderModule => wgpuShaderModuleAddRef(raw as WGPUShaderModule),
                Kind::Surface => wgpuSurfaceAddRef(raw as WGPUSurface),
                Kind::Texture => wgpuTextureAddRef(raw as WGPUTexture),
                Kind::TextureView => wgpuTextureViewAddRef(raw as WGPUTextureView),
            }
        }
    }
    /// `wgpu*Release` for an object of this type.
    pub unsafe fn release(self, raw: *mut c_void) {
        // SAFETY: the caller passes a live object of this type.
        unsafe {
            match self {
                Kind::Adapter => wgpuAdapterRelease(raw as WGPUAdapter),
                Kind::BindGroup => wgpuBindGroupRelease(raw as WGPUBindGroup),
                Kind::BindGroupLayout => wgpuBindGroupLayoutRelease(raw as WGPUBindGroupLayout),
                Kind::Buffer => wgpuBufferRelease(raw as WGPUBuffer),
                Kind::CommandBuffer => wgpuCommandBufferRelease(raw as WGPUCommandBuffer),
                Kind::CommandEncoder => wgpuCommandEncoderRelease(raw as WGPUCommandEncoder),
                Kind::ComputePassEncoder => wgpuComputePassEncoderRelease(raw as WGPUComputePassEncoder),
                Kind::ComputePipeline => wgpuComputePipelineRelease(raw as WGPUComputePipeline),
                Kind::Device => wgpuDeviceRelease(raw as WGPUDevice),
                Kind::ExternalTexture => wgpuExternalTextureRelease(raw as WGPUExternalTexture),
                Kind::Instance => wgpuInstanceRelease(raw as WGPUInstance),
                Kind::PipelineLayout => wgpuPipelineLayoutRelease(raw as WGPUPipelineLayout),
                Kind::QuerySet => wgpuQuerySetRelease(raw as WGPUQuerySet),
                Kind::Queue => wgpuQueueRelease(raw as WGPUQueue),
                Kind::RenderBundle => wgpuRenderBundleRelease(raw as WGPURenderBundle),
                Kind::RenderBundleEncoder => wgpuRenderBundleEncoderRelease(raw as WGPURenderBundleEncoder),
                Kind::RenderPassEncoder => wgpuRenderPassEncoderRelease(raw as WGPURenderPassEncoder),
                Kind::RenderPipeline => wgpuRenderPipelineRelease(raw as WGPURenderPipeline),
                Kind::Sampler => wgpuSamplerRelease(raw as WGPUSampler),
                Kind::ShaderModule => wgpuShaderModuleRelease(raw as WGPUShaderModule),
                Kind::Surface => wgpuSurfaceRelease(raw as WGPUSurface),
                Kind::Texture => wgpuTextureRelease(raw as WGPUTexture),
                Kind::TextureView => wgpuTextureViewRelease(raw as WGPUTextureView),
            }
        }
    }
}
